#include <iostream>
#include <string>

class Member {
    std::string name;
public:
    explicit Member(std::string n) : name(std::move(n)) {
        std::cout << "  [Member] " << name << " created\n";
    }
    ~Member() {
        std::cout << "  [Member] " << name << " destroyed\n";
    }
};

class Base {
    Member baseMember{"BaseMember"};
public:
    explicit Base(int val) {
        std::cout << " [Base] constructor with value: " << val << "\n";
    }
    virtual ~Base() {
        std::cout << " [Base] destructor\n";
    }
};

class Derived : public Base {
    Member derivedMember{"DerivedMember"};
public:
    // Inherit constructors from Base (C++11/C++17)
    using Base::Base;

    ~Derived() override {
        std::cout << "[Derived] destructor\n";
    }
};

int main() {
    std::cout << "--- Constructing Derived object ---\n";
    {
        Derived d(42);
        std::cout << "--- Object in scope ---\n";
    }
    std::cout << "--- Object out of scope ---\n";
    return 0;
}

#include <iostream>

class Engine {
public:
    void start() const {
        std::cout << "Engine started.\n";
    }
protected:
    void fuelPump() const {
        std::cout << "Fuel pumped.\n";
    }
private:
    int serialNumber{101};
};

// Public inheritance: represents 'is-a'
class SportsCar : public Engine {
public:
    void drive() {
        fuelPump(); // Accessible: protected in Engine -> protected in SportsCar
        start();    // Accessible: public in Engine -> public in SportsCar
        std::cout << "SportsCar zooming!\n";
    }
};

// Private inheritance: represents 'implemented-in-terms-of'
class Generator : private Engine {
public:
    void powerOn() {
        // start() and fuelPump() become private inside Generator
        start();
        std::cout << "Generator producing electricity.\n";
    }
};

int main() {
    SportsCar car;
    car.start(); // OK: public inheritance preserves public interface
    car.drive();

    Generator gen;
    gen.powerOn(); // OK: Generator's own public function
    // gen.start(); // ERROR: start() is private within Generator

    return 0;
}
